class ЛицензияНеизвестна(Exception):
    pass

def проверить_лицензию(ключ: str) -> bool:
    """
    Простейшая заглушка проверки лицензии по ключу.
    - Валидные ключи: содержат подстроку 'VALID' -> True
    - Невалидные/истёкшие: содержат 'INVALID' или 'EXPIRED' -> raise ЛицензияНедействительна
    - Неизвестный тип: содержат 'UNKNOWN' -> raise ЛицензияНеизвестна
    - Пустая строка -> raise ЛицензияНедействительна
    - Иначе -> False
    """
    if not ключ:
        raise ЛицензияНедействительна("Ключ пустой")
    key_up = ключ.upper()
    if "VALID" in key_up:
        return True
    if "INVALID" in key_up or "EXPIRED" in key_up:
        raise ЛицензияНедействительна("Ключ недействителен или истёк")
    if "UNKNOWN" in key_up:
        raise ЛицензияНеизвестна("Неизвестный тип лицензии")
    return False", "path": "/workspace/project/проверка_лицензий.py"}
